import { Annogram } from './annogram.js';
import poems from './poems.js';
import RiTa from 'rita';

function annogram() {
  return new Annogram(4, poems, { maxLengthMatch: 7, RiTa });
}

const allText = poems.map(p => p.text).join(' ');

function longestMatchRun(sentenceTokens) {
  // find the longest run of consecutive tokens from sentenceTokens that
  // appears verbatim (as untokenized text) somewhere in allText
  let best = 0;
  for (let start = 0; start < sentenceTokens.length; start++) {
    for (let len = sentenceTokens.length - start; len > best; len--) {
      const phrase = RiTa.untokenize(sentenceTokens.slice(start, start + len));
      if (allText.includes(phrase)) {
        best = Math.max(best, len);
        break;
      }
    }
  }
  return best;
}

let maxSeen = 0;
for (let trial = 0; trial < 20; trial++) {
  const mm = annogram();
  const poem = mm.generate(5, { minLength: 10 });
  const toks = RiTa.tokenize(poem.text.replace(/<p>/g, ' '));
  const run = longestMatchRun(toks);
  maxSeen = Math.max(maxSeen, run);
  console.log(`trial ${trial}: longest matching run = ${run}`);
}
console.log('MAX SEEN ACROSS TRIALS:', maxSeen, '(maxLengthMatch was 7)');

